using System;
class PassengerCareTests {
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok){Console.WriteLine("FAIL "+message);throw new Exception(message);}}
 static void Main(){
  Check(ScoreFeedback.Text("급제동 -2점",-2)=="급제동 · -2","short cause and actual delta without duplicate penalty");
  Check(ScoreFeedback.Text("요청 이행",5)=="요청 이행 · +5","short positive change");
  int waitingCount=0;for(int i=0;i<1000;i++){bool present=PassengerWaitingPolicy.Present("fixed-day",0,"stop"+i);Check(present==PassengerWaitingPolicy.Present("fixed-day",0,"stop"+i),"waiting seed does not flicker/reroll");if(present)waitingCount++;}Check(waitingCount>250&&waitingCount<450,"sparse roadside population includes occupied and empty candidates");
  var receipt=new PassengerResult{initialFare=5000,quoted=6000,paid=6200,cleanBonus=3,driveDelta=-43,satisfactionDelta=5};Check(RideReceiptSummary.Money(receipt)=="제시 운임  5,000원\n정산 증감  +1,200원\n최종 운임  6,200원","legacy receipt names a net fare change without claiming an actual bonus");
  receipt.paid=3500;Check(RideReceiptSummary.Money(receipt).Contains("정산 증감  -1,500원"),"fare reduction appears as signed settlement change");Check(RideReceiptSummary.Factors(receipt)=="청결 · +3\n주행 · -43\n요청 이행 · +5","receipt lists only nonzero short satisfaction causes");receipt.initialFare=0;Check(RideReceiptSummary.InitialFare(receipt)==6000,"old receipts without initial quote fall back without fake zeros");
  var reduced=new PassengerResult{initialFare=5000,quoted=5000,baseFare=3500,bonus=0,paid=3500,bonusReason="S below R"};Check(RideReceiptSummary.Money(reduced)=="제시 운임  5,000원\n정산 증감  -1,500원\n최종 운임  3,500원","M-based base reduction is not shown as a negative bonus");
  var actualBonus=new PassengerResult{initialFare=5000,quoted=5000,baseFare=5000,bonus=200,paid=5200,bonusReason="S meets R"};Check(RideReceiptSummary.Money(actualBonus)=="제시 운임  5,000원\n보너스  +200원\n최종 운임  5,200원","actual bonus keeps its label when base fare is unchanged");
  var mixed=new PassengerResult{initialFare=5000,quoted=5000,baseFare=3500,bonus=200,paid=3700,bonusReason="S meets R"};Check(RideReceiptSummary.Money(mixed).Contains("정산 증감  -1,300원"),"combined base reduction and bonus names the net settlement change");
  var reported=PassengerReward.CalculateDetailed(100,85,5000,5000,0,true,76,3,100,100,false);
  Check(reported.Breakdown.Contains("기본 73 + 청결 3 = 시작 76"),"receipt must explain cleanliness already included in 76, not an extra missing +3");
  var shown=PassengerScoreView.Live(76,3,85,100,0);Check(shown.value==76&&shown.Caption.Contains("요구 85"),"HUD shows S76 and R85 rather than internal M100");
  shown=PassengerScoreView.Live(76,3,85,98,5);Check(shown.value==79&&shown.drive==-2&&shown.request==5,"live driving -2 and request +5 update displayed79");
  var finished=PassengerReward.CalculateDetailed(98,85,5000,5000,5,true,76,3,100,100,false);Check(PassengerScoreView.Settled(finished).value==shown.value,"equal arrival ETA does not change live score or add clean3 twice");
  Check(PassengerScoreView.Settled(PassengerReward.CalculateDetailed(98,85,5000,5000,5,true,76,3,100,80,false)).value==91,"safe early time+12 joins same score at arrival only");
  Check(PassengerScoreView.Live(97,3,100,100,8).value==100&&PassengerScoreView.Live(3,0,60,0,-10).value==0,"display clamps exactly like reward");
  var lawView=new LawLedger();var lawEvent=new LawEvent{id="score-ui-violation",day=1};lawEvent.Add("red",LawVerdict.Violation,20);lawView.Record(lawEvent);Check(lawView.TotalScore==80&&shown.value==79,"independent law20 does not replace passenger79");
  var goodEvent=new LawEvent{id="score-ui-compliant",day=2};goodEvent.Add("yield",LawVerdict.Compliant,0);lawView.Record(goodEvent);Check(lawView.TotalScore==81,"actual compliance raises cumulative score by1 across days");var savedLaw=new LawLedger();foreach(var item in lawView.Events)savedLaw.Record(item);Check(savedLaw.TotalScore==81&&!savedLaw.Record(goodEvent),"restored law score and event dedup unchanged");
  var care=new VehicleCare();Check(care.Cleanliness==100&&care.BoardingBonus==3,"new campaign clean100 and boarding +3");
  Check(care.Finish("plain",false)&&care.Cleanliness==98&&!care.Finish("plain",true),"normal -2 once per trip");
  Check(care.Finish("vomit",true)&&care.Cleanliness==10,"vomit min10 instead of -2");Check(care.Refuse("offer1")&&care.AcceptanceLocked&&care.Refusals==1&&!care.Refuse("offer1"),"refusal once; no ride identity created");
  var restored=VehicleCare.Restore(care.Snapshot());restored.BeginDay(2);Check(restored.Cleanliness==10&&restored.AcceptanceLocked&&restored.Refusals==1&&!restored.Finish("vomit",false),"care/de-dup/refusal survives day+snapshot");restored.Wash();Check(restored.Cleanliness==100&&!restored.AcceptanceLocked,"wash removes lock");Check(restored.BoardDrunk()&&!restored.BoardDrunk(),"daily drunk boarded cap1");restored.BeginDay(3);Check(restored.BoardDrunk(),"daily cap resets");
  foreach(int cleanliness in new[]{0,29,30,79,80,100}){var threshold=VehicleCare.Restore(new VehicleCareSnapshot{cleanliness=cleanliness});Check(threshold.NeedsWash==(cleanliness<30)&&threshold.BoardingBonus==(cleanliness>=80?3:0),"cleanliness refusal/bonus threshold "+cleanliness);}
  foreach(var kind in new[]{DrunkRideCase.Normal,DrunkRideCase.Vomit,DrunkRideCase.Sleepy,DrunkRideCase.Both}){var ride=DrunkRideState.Create("fixed-"+kind,true,kind);Check(ride.IsDrunk==(kind!=DrunkRideCase.Normal),"fixed normal/drunk");Check(ride.VomitProgress>=.3f&&ride.VomitProgress<=.7f,"vomit progress range");Check(!ride.Advance(10,.29f),"never before30 percent");bool vomit=ride.Advance(10,.71f);Check(vomit==(kind==DrunkRideCase.Vomit||kind==DrunkRideCase.Both),"fixed vomit");Check(!ride.Advance(1,1),"vomit single event");Check(ride.Arrive(true)&&!ride.Arrive(false),"first arrival immutable");var copy=ride.Copy();Check(copy.ArrivalElapsed==21&&copy.OnTime,"saved arrival time");bool sleepy=kind==DrunkRideCase.Sleepy||kind==DrunkRideCase.Both;Check(copy.Waiting==sleepy,"independent sleep selection");if(sleepy){Check(!copy.Disembark(true,true),"wake at0 rejected");copy.Advance(14.99f,1);Check(!copy.Disembark(true,true),"wake before15 rejected");copy.Advance(.01f,1);Check(!copy.Disembark(false,true),"unsafe departure blocked");Check(copy.Disembark(true,true)&&!copy.Disembark(true,true),"wake15 single settlement");var auto=ride.Copy();auto.Advance(30,1);Check(!auto.Disembark(false,false)&&auto.Disembark(true,false),"30 seconds wait returns to safe stop");}else Check(copy.Disembark(true,false),"ordinary immediate disembark");}
  int drunkCount=0,vomitCount=0,sleepCount=0;for(int i=0;i<10000;i++){var r=DrunkRideState.Create("candidate"+i,true);var same=DrunkRideState.Create("candidate"+i,true);Check(r.IsDrunk==same.IsDrunk&&r.SleepPlanned==same.SleepPlanned&&r.VomitProgress==same.VomitProgress,"stable repeated candidate");if(r.IsDrunk){drunkCount++;if(r.VomitPlanned)vomitCount++;if(r.SleepPlanned)sleepCount++;}}Check(drunkCount>1700&&drunkCount<2300,"20 percent candidate probability");Check(vomitCount>drunkCount*.20&&vomitCount<drunkCount*.30,"25 percent conditional vomit");Check(sleepCount>drunkCount*.25&&sleepCount<drunkCount*.35,"30 percent conditional sleep");Check(!DrunkRideState.Create("fixed",false,DrunkRideCase.Both).IsDrunk,"daily cap suppresses drunk candidate");
  var trip=new FareTrip();trip.Accept(5000,1);trip.Board();trip.Tick(.5f);Check(trip.LockArrival(),"lock first valid arrival");trip.Tick(30);Check(trip.Remaining==.5f&&trip.ArrivedOnTime,"deadline freeze while business time advances");var saved=trip.Snapshot();var resume=new FareTrip();resume.Restore(saved);Check(resume.ArrivalLocked&&resume.Complete()==5000&&resume.Complete()==0,"arrival freeze save and one-time fare");trip.Clear();trip.Accept(5000,1);trip.Board();trip.Tick(2);trip.LockArrival();Check(!trip.ArrivedOnTime&&trip.Complete()==0&&trip.State==TripState.Failed,"late before arrival zero");
  var settings=PrototypeSettings.ForThreeDays();settings.startCash=500;var economy=new EconomyLedger(settings);economy.Care.Finish("dirty",true);double before=economy.Elapsed;Check(economy.UseWash("wash1"),"wash affordable through debt");Check(economy.Elapsed==before+30&&economy.Care.Cleanliness==100,"wash30seconds clean100");Check(economy.Account.Cash==0&&economy.Account.Debt==1500&&economy.Account.Expense(1,"wash")==2000,"wash paid500 debt1500 expense2000");Check(!economy.UseWash("wash1")&&economy.Elapsed==30&&economy.Account.Expense(1,"wash")==2000,"duplicate wash no cost/time");var finance=CampaignAccount.Restore(economy.Account.Snapshot());Check(!finance.Wash("wash1",1)&&finance.Debt==1500,"wash identity survives restore");economy.Advance(economy.SecondsLeft-29,0);Check(!economy.UseWash("wash2")&&economy.Account.Expense(1,"wash")==2000,"29 seconds remaining blocks wash without payment");
  var exact=new EconomyLedger(settings);exact.Advance(exact.SecondsLeft-30,0);Check(exact.UseWash("boundary")&&exact.State==BusinessState.Closing,"exactly30seconds wash allowed, closes");
  foreach(int required in new[]{60,70,85}){int d=PassengerReward.Deficit("trip"+required);Check(d==4||d==8||d==12,"deficit catalog");Check(d==PassengerReward.Deficit("trip"+required),"deficit stable by trip");}
  var equal=PassengerReward.CalculateDetailed(100,85,5000,5000,0,true,85,0,100,100,false);Check(equal.bonus==100,"S=R minimum20percent");var high=PassengerReward.CalculateDetailed(100,85,5000,5000,0,true,93,0,100,100,false);Check(high.bonus==310,"S93 common bonus310");Check(PassengerReward.CalculateDetailed(100,85,5000,5000,0,true,100,0,100,100,false).bonus==500,"S100cap500");Check(PassengerReward.CalculateDetailed(80,85,5000,3500,8,true,100,0,100,100,false).bonus>0,"70percent base still eligible");Check(PassengerReward.CalculateDetailed(100,70,5000,5000,0,true,62,0,100,90,false).timeDelta==6,"10percent early6");Check(PassengerReward.CalculateDetailed(100,70,5000,5000,0,true,62,0,100,80,false).timeDelta==12,"20percent early12cap");Check(PassengerReward.CalculateDetailed(100,70,5000,5000,0,true,62,0,100,80,true).timeDelta==0,"unsafe only cancels time bonus");Check(PassengerReward.CalculateDetailed(100,70,5000,5000,0,true,100,0,0,0,false).timeDelta==0,"invalid reference zero");Check(PassengerReward.CalculateDetailed(100,70,5000,5000,0,false,100,0,100,80,false).Total==0,"late zero base+bonus");Check(PassengerRequest.Delta(RequestKind.Quiet,true)==5&&PassengerRequest.Delta(RequestKind.LostItem,true)==0&&PassengerRequest.Delta(RequestKind.RejectIllegal,true)==0,"quiet fulfillment and neutral after-trip/illegal");
  Console.WriteLine("PASS passenger care "+checks+" assertions: four fixed rides, probabilities, safe15/30wake, first arrival, care/day/save, wash debt+time+idempotency, satisfaction/common bonus");
 }
}
